import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, DoubleSide, Color } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const group = new Group();

  // Create cleanup list
  const activeTimelines = [];
  const activePrimitives = [];

  // Theme definition
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. Stage Backdrop (Engineered Gradient Surface - dark-first aesthetic)
  const backdropGeo = new PlaneGeometry(7.2, 5.8);
  const backdropMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
    opacity: 0.85
  });

  // TSL Graph: Vertical gradient + Subtle procedural grain mock
  const uvNode = uv();
  const topColor = vec3(
    new Color(colors.surface).r,
    new Color(colors.surface).g,
    new Color(colors.surface).b
  );
  const bottomColor = vec3(
    new Color(colors.ink).r,
    new Color(colors.ink).g,
    new Color(colors.ink).b
  );
  const gradient = mix(bottomColor, topColor, uvNode.y);
  backdropMat.colorNode = gradient;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // 2. High Contrast Accent Line (Signal edge)
  const accentLineGeo = new PlaneGeometry(1.6, 0.02);
  const accentLineMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    side: DoubleSide
  });
  const accentLine = new Mesh(accentLineGeo, accentLineMat);
  accentLine.position.set(-1.0, 0.4, 0.01);
  group.add(accentLine);

  // 3. Main Image Plane (Optional textured surface from config.imageUrl if present)
  let imageMesh = null;
  if (config.imageUrl) {
    const imgGeo = new PlaneGeometry(2.4, 1.5);
    const imgMat = new MeshBasicNodeMaterial({
      transparent: true,
      side: DoubleSide,
      opacity: 0.95
    });

    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imgMat.map = texture;
      imgMat.needsUpdate = true;
    });

    imageMesh = new Mesh(imgGeo, imgMat);
    imageMesh.position.set(0, -0.6, 0.02);
    group.add(imageMesh);
  }

  // 4. Text Layout (Using ctx.fontAtlas as strictly specified)
  const textGroup = new Group();
  textGroup.position.set(-1.8, 0.7, 0.05);

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const primaryTextString = textItems[0]?.text ?? "Features 1";

  // Create High-Contrast Mono Display Title
  const titleText = ctx.fontAtlas.createText(primaryTextString, {
    fontSize: 48,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 1.2
  });
  textGroup.add(titleText);

  // Subtitle decoration / metadata indicator (Atelier brand mark)
  const decoratorText = ctx.fontAtlas.createText("NOVA ATELIER // SPEC-01", {
    fontSize: 16,
    color: colors.accent,
    align: 'left',
    letterSpacingPx: 2.0
  });
  decoratorText.position.set(0, 0.35, 0);
  textGroup.add(decoratorText);

  group.add(textGroup);

  // 5. Entrance Choreography (Rise-In & Settle)
  group.position.y += 0.4;
  group.scale.set(0.95, 0.95, 0.95);

  const settleTl = gsap.timeline();
  settleTl.to(group.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out'
  });
  settleTl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  activeTimelines.push(settleTl);

  // Apply Cinematic Primitives if available in config
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const primRef = ctx.primitives[primitive.name](group, primitive.params);
        if (primRef) {
          activePrimitives.push(primRef);
          if (primRef.timeline) {
            activeTimelines.push(primRef.timeline);
          }
        }
      }
    });
  }

  // Clean implementation with no memory leaks
  group.userData.cleanup = function() {
    activeTimelines.forEach((tl) => tl.kill());
    activePrimitives.forEach((prim) => {
      if (typeof prim.cleanup === 'function') {
        prim.cleanup();
      }
    });
    backdropGeo.dispose();
    backdropMat.dispose();
    accentLineGeo.dispose();
    accentLineMat.dispose();
  };

  return group;
}
